+package com.example;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.element.ButtonElement;
+import org.vaadin.addons.dramafinder.element.DialogElement;
+import org.vaadin.addons.dramafinder.element.EmailFieldElement;
+import org.vaadin.addons.dramafinder.element.GridElement;
+import org.vaadin.addons.dramafinder.element.NotificationElement;
+import org.vaadin.addons.dramafinder.element.TextAreaElement;
+import org.vaadin.addons.dramafinder.element.TextFieldElement;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+public class ContactViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port;
+    }
+
+    private void openContact() {
+        page.navigate(getUrl() + "/contact");
+        page.waitForSelector("h1");
+    }
+
+    @Test
+    void headingsAndLinkWork() {
+        openContact();
+        assertEquals("Contact", page.locator("h1").innerText());
+
+        page.getByText("About", new com.microsoft.playwright.Page.GetByTextOptions().setExact(true)).click();
+        page.waitForURL("**/about");
+        assertEquals("About", page.locator("h1").innerText());
+    }
+
+    @Test
+    void emptyFormValidationShowsErrors() {
+        openContact();
+        ButtonElement send = ButtonElement.getByText(page, "Send");
+        send.click();
+
+        TextFieldElement name = TextFieldElement.getByLabel(page, "Name");
+        EmailFieldElement email = EmailFieldElement.getByLabel(page, "Email");
+        TextAreaElement message = TextAreaElement.getByLabel(page, "Message");
+
+        page.waitForCondition(() -> Boolean.TRUE.equals(name.getProperty("invalid")));
+
+        assertTrue((Boolean) name.getProperty("invalid"));
+        assertEquals("Name is required", name.getProperty("errorMessage"));
+
+        assertTrue((Boolean) email.getProperty("invalid"));
+        assertEquals("Give an e-mail address or a phone number", email.getProperty("errorMessage"));
+
+        assertTrue((Boolean) message.getProperty("invalid"));
+        assertEquals("Message is required", message.getProperty("errorMessage"));
+    }
+
+    @Test
+    void successfulSendShowsNotificationAndClearsForm() {
+        openContact();
+        TextFieldElement name = TextFieldElement.getByLabel(page, "Name");
+        TextFieldElement phone = TextFieldElement.getByLabel(page, "Phone");
+        TextAreaElement message = TextAreaElement.getByLabel(page, "Message");
+
+        name.setValue("Alice Browser");
+        phone.setValue("123456");
+        message.setValue("Hello from a real browser");
+
+        GridElement grid = GridElement.get(page);
+        int before = grid.getTotalRowCount();
+
+        ButtonElement send = ButtonElement.getByText(page, "Send");
+        send.click();
+
+        NotificationElement notification = NotificationElement.getByText(page, "Message sent");
+        notification.assertOpen();
+
+        assertEquals("", name.getValue());
+        assertEquals("", phone.getValue());
+        assertEquals("", message.getValue());
+
+        assertTrue(Boolean.TRUE.equals(send.getProperty("disabled")));
+
+        page.waitForCondition(() -> grid.getTotalRowCount() == before + 1);
+    }
+
+    @Test
+    void leavingWithDataPromptsDialog() {
+        openContact();
+        TextFieldElement name = TextFieldElement.getByLabel(page, "Name");
+        name.setValue("Someone typing");
+
+        page.getByText("About", new com.microsoft.playwright.Page.GetByTextOptions().setExact(true)).click();
+
+        DialogElement dialog = new DialogElement(page);
+        dialog.assertOpen();
+
+        ButtonElement keepEditing = ButtonElement.getByText(dialog.getFooterLocator(), "Keep editing");
+        keepEditing.click();
+
+        assertEquals("Someone typing", name.getValue());
+        assertEquals("Contact", page.locator("h1").innerText());
+    }
+}
